"""Sender ID corridor classification and resolution for outbound SMS.

Which destinations accept a dynamic (unregistered) alphanumeric sender ID
comes from Twilio's per-country SMS guidelines
(https://www.twilio.com/en-us/guidelines/<cc>/sms, "Alphanumeric" table,
"Twilio supported" row). ``_REGION_OUTCOMES`` is generated by
scripts/sender_id_corridors.py (fetched 2026-10-18) — rerun the script
instead of editing it by hand. A region the script leaves out (no
guidelines page) requires the org's dedicated number.

Outcomes:

- ``custom_ok`` — a dynamic sender ID reaches the handset as sent.
- ``excluded`` — operators replace the ID with a random code, so the brand
  would not show (India, Finland, Mexico, ...); a dedicated number is used.
- ``always_number`` — Twilio does not support a dynamic sender ID there, or
  only on some networks (US, Canada, Spain, Czech Republic, ...).
- ``platform_default_only`` — pre-registration required; Hail registered
  the platform default ``HAIL`` (Australia).
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

import phonenumbers

__all__ = ["SenderResolution", "resolve_sender"]

PLATFORM_DEFAULT_SENDER_ID = "HAIL"

CorridorOutcome = Literal[
    "always_number", "custom_ok", "platform_default_only", "excluded"
]

